71	/**
72	 * Channel to a remote JournalNode using Hadoop IPC.
73	 * All of the calls are run on a separate thread, and return
74	 * {@link ListenableFuture} instances to wait for their result.
75	 * This allows calls to be bound together using the {@link QuorumCall}
76	 * class.
77	 */
78	@InterfaceAudience.Private
79	public class IPCLoggerChannel implements AsyncLogger {
80	
81	  private final Configuration conf;
82	  protected final InetSocketAddress addr;
83	  private QJournalProtocol proxy;
84	
85	  /**
86	   * Executes tasks submitted to it serially, on a single thread, in FIFO order
87	   * (generally used for write tasks that should not be reordered).
88	   */
89	  private final ListeningExecutorService singleThreadExecutor;
90	  /**
91	   * Executes tasks submitted to it in parallel with each other and with those
92	   * submitted to singleThreadExecutor (generally used for read tasks that can
93	   * be safely reordered and interleaved with writes).
94	   */
95	  private final ListeningExecutorService parallelExecutor;
96	  private long ipcSerial = 0;
97	  private long epoch = -1;
98	  private long committedTxId = HdfsServerConstants.INVALID_TXID;
99	  
100	  private final String journalId;
101	  private final String nameServiceId;
102	
103	  private final NamespaceInfo nsInfo;
104	
105	  private URL httpServerURL;
106	
107	  private final IPCLoggerChannelMetrics metrics;
108	  
109	  /**
110	   * The number of bytes of edits data still in the queue.
111	   */
112	  private int queuedEditsSizeBytes = 0;
113	  
114	  /**
115	   * The highest txid that has been successfully logged on the remote JN.
116	   */
117	  private long highestAckedTxId = 0;
118	
119	  /**
120	   * Nanotime of the last time we successfully journaled some edits
121	   * to the remote node.
122	   */
123	  private long lastAckNanos = 0;
124	
125	  /**
126	   * Nanotime of the last time that committedTxId was update. Used
127	   * to calculate the lag in terms of time, rather than just a number
128	   * of txns.
129	   */
130	  private long lastCommitNanos = 0;
131	  
132	  /**
133	   * The maximum number of bytes that can be pending in the queue.
134	   * This keeps the writer from hitting OOME if one of the loggers
135	   * starts responding really slowly. Eventually, the queue
136	   * overflows and it starts to treat the logger as having errored.
137	   */
138	  private final int queueSizeLimitBytes;
139	
140	  /**
141	   * If this logger misses some edits, or restarts in the middle of
142	   * a segment, the writer won't be able to write any more edits until
143	   * the beginning of the next segment. Upon detecting this situation,
144	   * the writer sets this flag to true to avoid sending useless RPCs.
145	   */
146	  private boolean outOfSync = false;
147	  
148	  /**
149	   * Stopwatch which starts counting on each heartbeat that is sent
150	   */
151	  private final StopWatch lastHeartbeatStopwatch = new StopWatch();
152	  
153	  private static final long HEARTBEAT_INTERVAL_MILLIS = 1000;
154	
155	  private static final long WARN_JOURNAL_MILLIS_THRESHOLD = 1000;
