172	  public IPCLoggerChannel(Configuration conf,
173	                          NamespaceInfo nsInfo,
174	                          String journalId,
175	                          String nameServiceId,
176	                          InetSocketAddress addr) {
177	    this.conf = conf;
178	    this.nsInfo = nsInfo;
179	    this.journalId = journalId;
180	    this.nameServiceId = nameServiceId;
181	    this.addr = addr;
182	    this.queueSizeLimitBytes = 1024 * 1024 * conf.getInt(
183	        DFSConfigKeys.DFS_QJOURNAL_QUEUE_SIZE_LIMIT_KEY,
184	        DFSConfigKeys.DFS_QJOURNAL_QUEUE_SIZE_LIMIT_DEFAULT);
185	    
186	    singleThreadExecutor = MoreExecutors.listeningDecorator(
187	        createSingleThreadExecutor());
188	    parallelExecutor = MoreExecutors.listeningDecorator(
189	        createParallelExecutor());
190	    
191	    metrics = IPCLoggerChannelMetrics.create(this);
192	  }
